const { Kysely, DummyDriver, PostgresAdapter, PostgresIntrospector, PostgresQueryCompiler } = require('/app/dist/cjs/index.js')
const db = new Kysely({ dialect: { createAdapter: () => new PostgresAdapter(), createDriver: () => new DummyDriver(), createIntrospector: (db) => new PostgresIntrospector(db), createQueryCompiler: () => new PostgresQueryCompiler() } })
const check = (name, q, sql, params=[]) => { const c=q.compile(); console.log(c.sql===sql && JSON.stringify(c.parameters)===JSON.stringify(params) ? 'PASS '+name : 'FAIL '+name+'\n got '+c.sql+' '+JSON.stringify(c.parameters)+'\n exp '+sql+' '+JSON.stringify(params)) }

let q = db.selectFrom('person').select(['a','b']).groupByCube((eb) => [eb.ref('first_name'), eb.ref('last_name')])
check('groupByCube callback', q, 'select "a", "b" from "person" group by cube ("first_name", "last_name")')

q = db.selectFrom('person').select(['a']).groupByGroupingSets(['first_name'], (eb) => [eb.ref('last_name')])
check('groupByGroupingSets callback set', q, 'select "a" from "person" group by grouping sets (("first_name"), ("last_name"))')

// single column cube
q = db.selectFrom('person').select(['a']).groupByCube('first_name')
check('groupByCube single', q, 'select "a" from "person" group by cube ("first_name")')

// grouping sets single element set
q = db.selectFrom('person').select(['a']).groupByGroupingSets(['first_name'])
check('groupByGroupingSets one set', q, 'select "a" from "person" group by grouping sets (("first_name"))')

// grouping sets with single column as array-of-array
q = db.selectFrom('person').select(['a']).groupByGroupingSets(['first_name'], ['last_name'])
check('groupByGroupingSets two sets', q, 'select "a" from "person" group by grouping sets (("first_name"), ("last_name"))')
EOF
